'use strict';

// MODULES //

var Uint32Array = require( '@stdlib/array/uint32' );
var getHighWord = require( '@stdlib/number/uint64/base/get-high-word' );
var getLowWord = require( '@stdlib/number/uint64/base/get-low-word' );
var Uint64 = require( '@stdlib/number/uint64/ctor' ); // eslint-disable-line stdlib/no-single-property-require
var assign = require( './assign.js' );


// VARIABLES //

var WORKSPACE = new Uint32Array( 2 );


// MAIN //

/**
* Computes the bitwise XOR of two 64-bit unsigned integers.
*
* @param {Uint64} a - 64-bit unsigned integer
* @param {Uint64} b - 64-bit unsigned integer
* @returns {Uint64} result
*
* @example
* var Uint64 = require( '@stdlib/number/uint64/ctor' );
*
* var a = new Uint64( 5 );
* var b = new Uint64( 15 );
*
* var v = xor( a, b );
* // returns <Uint64>[ 10n ]
*/
function xor( a, b ) {
	assign( getHighWord( a ), getLowWord( a ), getHighWord( b ), getLowWord( b ), WORKSPACE, 1, 0 ); // eslint-disable-line max-len
	return Uint64.of( WORKSPACE[ 0 ], WORKSPACE[ 1 ] );
}


// EXPORTS //

module.exports = xor;
